% Author: Writer agent · 2026-11-14
% Task W2: Chapter 6 (generic pipeline). Sources: research-notes.md, Ch. 6 (+ Ch. 2, 3 keys for blocks 1 and 3).
% The eight-block division is the BOOK'S OWN educational simplification (see Gaps in research-notes.md).

\chapter{שמונה תחנות בדרך לשיר הבא}\label{ch:6}

\begin{scene}
21:00. נועה מבשלת שקשוקה, ידיים מלאות עגבניות. היא לוחצת על הטלפון עם המרפק: „תני משהו". חצי שנייה אחר כך כבר מתנגן שיר, והוא מתאים בדיוק לשקשוקה.

„רגע", היא אומרת למחבת, „מה קרה בחצי השנייה הזאת?"

המחבת, כמו הטלפון בפרק~\ref{ch:1}, לא עונה. אבל הפרק הזה כן.
\end{scene}

\begin{figure}[t]
  \centering
  \input{figures/pipeline.tex}
  \caption{תהליך ההמלצה בשמונה תחנות: פישוט לימודי של הספר, ולא הארכיטקטורה הפנימית של פלטפורמה כלשהי \educational}
  \label{fig:pipeline}
\end{figure}

\section{מפה לימודית, לא שרטוט של מפעל}

איור~\ref{fig:pipeline} מחבר את כל מה שלמדנו לתהליך אחד. חשוב לומר ביושר: החלוקה לשמונה תחנות היא פישוט לימודי שלנו, ולא תיאור של המערכת של חברה כלשהי. המקורות תומכים בדפוס הכללי. לפי המדריך של \en{Google}, מערכת המלצה מתחילה מאוסף ענק ומצמצמת אותו לקבוצה קטנה בהרבה של מועמדים, אחר כך מדרגת אותם, ולבסוף מתחשבת באילוצים נוספים לפני הדירוג הסופי \cite{google2026overview}. מאמר של \en{YouTube} מ-2016 מתאר מבנה דומה של שני שלבים: מודל ליצירת מועמדים ומודל נפרד לדירוג \cite{covington2016deep}. גם לולאת המשוב מתועדת במחקר \cite{chaney2018algorithmic}. שלוש התחנות הראשונות הן מסגור סביר שלנו, אבל אין מקור אחד שמונה את כל שמונה התחנות.

\section{התחנות, בערב של נועה}

\begin{enumerate}
  \item \textbf{איסוף אותות.} כל פעולה של נועה נרשמת: הדילוג של 23:00 מפרק~\ref{ch:5}, השמירה של שיר האינדי מפרק~\ref{ch:4}. לפי \en{Spotify}, חיפוש, האזנה, דילוג ושמירה משפיעים על האופן שבו היא מפרשת את הטעם \cite{spotify2026understanding}.
  \item \textbf{ניקוי ואיחוד נתונים.} מאחדים את האירועים מהטלפון ומהמחשב, ומנסים לזהות רעש. למשל, שיר שהתנגן שעה כשהטלפון נשכח בכיס הוא לא בהכרח שיר אהוב.
  \item \textbf{ייצוג משתמשים ושירים.} נועה וכל שיר הופכים לייצוג וקטורי, כלומר לנקודה במרחב משותף, כמו בפרק~\ref{ch:3} \cite{google2026candidate}.
  \item \textbf{\term{יצירת מועמדים}{candidate generation}.} מתוך הקטלוג העצום נבחרת קבוצה קטנה בהרבה \cite{google2026overview}: שירים שיוני אוהב, שירים שדומים לשיר האינדי. לפי \en{Spotify}, האלגוריתמים שלה מתחשבים גם במגמות ובטעם הכללי של כלל המשתמשים \cite{spotify2026understanding}.
  \item \textbf{\term{דירוג}{ranking}.} מודל נפרד נותן ציון לכל מועמד ומסדר את הרשימה \cite{covington2016deep}. השאלה היא בערך: „מה הסיכוי שנועה תשמע את זה עד הסוף, עכשיו?"
  \item \textbf{סינון וגיוון.} ב\term{דירוג מחדש}{re-ranking} אפשר להסיר פריטים שהמשתמש סימן במפורש שאינו אוהב, לתת דחיפה לתוכן טרי, ולעזור להבטיח גיוון, רעננות והוגנות \cite{google2026overview}. כך לא יתנגנו עשרה שירים של אותה זמרת ברצף. לפי הפישוט שלנו, זה גם מקום טבעי לחקירה מפרק~\ref{ch:5}.
