  \item \textbf{סינון וגיוון.} ב\term{דירוג מחדש}{re-ranking} אפשר להסיר פריטים שהמשתמש סימן במפורש שאינו אוהב, לתת דחיפה לתוכן טרי, ולעזור להבטיח גיוון, רעננות והוגנות \cite{google2026overview}. כך לא יתנגנו עשרה שירים של אותה זמרת ברצף. לפי הפישוט שלנו, זה גם מקום טבעי לחקירה מפרק~\ref{ch:5}.
  \item \textbf{הצגת המלצות.} השיר הראשון מתנגן ליד השקשוקה, ושאר הרשימה מחכה בתור.
  \item \textbf{משוב ולמידה.} התגובה של נועה הופכת לאות חדש. לפי \en{Spotify}, לחיצה על „לא מעוניין", אגודל למטה או הסתרה מובילה לפחות המלצות דומות \cite{spotify2026understanding}.
\end{enumerate}

החץ המקווקו בין התחנה האחרונה לראשונה הוא \term{לולאת משוב}{feedback loop}. מערכות המלצה מאומנות לעיתים קרובות על נתונים של משתמשים שכבר ראו המלצות. לפי צ'ייני ועמיתיו, זה יוצר לולאת משוב מזיקה, ובסימולציות שלהם היא האחידה את התנהגות המשתמשים בלי להגדיל את התועלת שלהם \cite{chaney2018algorithmic}. במה זה נוגע לנועה? על כך בפרק הבא.

\begin{inshort}
\begin{itemize}
  \item שמונה התחנות הן פישוט לימודי של הספר, ולא המערכת של חברה כלשהי.
  \item הליבה מתועדת במקורות: יצירת מועמדים, דירוג, ואז סינון וגיוון.
  \item כל תגובה של נועה חוזרת לתחנה הראשונה וסוגרת לולאת משוב.
\end{itemize}
\end{inshort}

